import os,json,hashlib;from pathlib import Path
assert os.geteuid()==10001
root=Path('/graphs');result={}
for p in [root,*sorted(root.rglob('*'))]:
 s=p.stat()
 result[str(p.relative_to(root))]={
  'sha256':hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None,
  'mtime_ns':s.st_mtime_ns,'size':s.st_size,'mode':s.st_mode,
  'uid':s.st_uid,'gid':s.st_gid}
print(json.dumps({'reader_uid':os.geteuid(),'files':result},sort_keys=True))

